from math import sqrt
from math import isclose
from .point import Point
from .disc import Disc
from .get_distance import get_distance
from .disc_from_two_points import disc_from_two_points

##all code generated by GPT 5.6
def disc_from_three_points(
    p1: Point,
    p2: Point,
    p3: Point
) -> Disc:
    denominator = 2 * (
        p1.x * (p2.y - p3.y)
        + p2.x * (p3.y - p1.y)
        + p3.x * (p1.y - p2.y)
    )

    if isclose(denominator, 0.0, abs_tol=1e-12):
        d12 = get_distance(p1,p2)
        d13 = get_distance(p1,p3)
        d23 = get_distance(p2,p3)

        if d12 >= d13 and d12 >= d23:
            return disc_from_two_points(p1, p2)
        elif d13 >= d12 and d13 >= d23:
            return disc_from_two_points(p1, p3)
        else:
            return disc_from_two_points(p2, p3)

    cx = (
        (p1.x ** 2 + p1.y ** 2) * (p2.y - p3.y)
        + (p2.x ** 2 + p2.y ** 2) * (p3.y - p1.y)
        + (p3.x ** 2 + p3.y ** 2) * (p1.y - p2.y)
    ) / denominator

    cy = (
        (p1.x ** 2 + p1.y ** 2) * (p3.x - p2.x)
        + (p2.x ** 2 + p2.y ** 2) * (p1.x - p3.x)
        + (p3.x ** 2 + p3.y ** 2) * (p2.x - p1.x)
    ) / denominator

    center = Point(cx, cy)
    radius = get_distance(center, p1)

    return Disc(center, radius)


# Right triangle
assert disc_from_three_points(
    Point(0, 0),
    Point(1, 0),
    Point(0, 1)
) == Disc(
    Point(0.5, 0.5),
    sqrt(2) / 2
)

# Same triangle, but translated and enlarged
assert disc_from_three_points(
    Point(1, 1),
    Point(3, 1),
    Point(1, 3)
) == Disc(
    Point(2, 2),
    sqrt(2)
)

# Circle centered at the origin with radius 1
assert disc_from_three_points(
    Point(1, 0),
    Point(0, 1),
    Point(-1, 0)
) == Disc(
    Point(0, 0),
    1
)

# Circle centered at (2, 3) with radius 2
assert disc_from_three_points(
    Point(4, 3),
    Point(2, 5),
    Point(0, 3)
) == Disc(
    Point(2, 3),
    2
)

# Same points as the first test, but in a different order
assert disc_from_three_points(
    Point(0, 1),
    Point(0, 0),
    Point(1, 0)
) == Disc(
    Point(0.5, 0.5),
    sqrt(2) / 2
)

# Three collinear horizontal points:
# the farthest pair is (0, 0) and (4, 0)
assert disc_from_three_points(
    Point(0, 0),
    Point(1, 0),
    Point(4, 0)
) == Disc(
    Point(2, 0),
    2
)

# Three collinear vertical points:
# the farthest pair is (0, -2) and (0, 4)
assert disc_from_three_points(
    Point(0, -2),
    Point(0, 1),
    Point(0, 4)
) == Disc(
    Point(0, 1),
    3
)